def get_me(api_key, **_extra):
    import json, os, datetime, time, hashlib, random
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0002000" if __import__("os").path.isdir("./environment_mix/0002000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _today_utc():
        return datetime.datetime.utcnow().date().isoformat()

    def _log(endpoint, client_id, status, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        rec = {
            "id": "req_" + hashlib.sha256(f"{endpoint}|{client_id}|{time.time()}|{random.random()}".encode("utf-8")).hexdigest()[:24],
            "endpoint": endpoint,
            "client_id": client_id,
            "status": status,
            "error_code": error_code,
            "latency_ms": int(max(0, (time.time() - t0) * 1000)),
            "created_at": now
        }
        logs.append(rec)
        _save("request_logs.json", logs)

    if not isinstance(api_key, str) or not api_key:
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string", error_code="invalid_argument")

    clients = _load("api_clients.json")
    if not isinstance(clients, list):
        clients = []

    # Authenticate by matching provided value either to client id OR api_key_hash (client-visible)
    client = None
    for c in clients:
        if not isinstance(c, dict):
            continue
        if c.get("id") == api_key or c.get("api_key_hash") == api_key:
            client = c
            break
    if client is None:
        _log("get_me", None, "error", "unauthorized")
        return _err("UNAUTHORIZED", "Invalid API key")

    # Usage counts for today
    day = _today_utc()
    gens = _load("generation_requests.json")
    if not isinstance(gens, list):
        gens = []
    downs = _load("download_events.json")
    if not isinstance(downs, list):
        downs = []

    req_total = 0
    img_total = 0
    txt_total = 0
    dl_total = 0
    for r in gens:
        if isinstance(r, dict) and r.get("client_id") == client.get("id"):
            ca = r.get("created_at")
            if isinstance(ca, str) and ca[:10] == day:
                req_total += 1
                if r.get("kind") == "image":
                    img_total += 1
                elif r.get("kind") == "text":
                    txt_total += 1
    for d in downs:
        if isinstance(d, dict) and d.get("client_id") == client.get("id"):
            ca = d.get("created_at")
            if isinstance(ca, str) and ca[:10] == day:
                dl_total += 1
                req_total += 1

    limits = {
        "daily_request_limit": int(client.get("daily_request_limit", 0)),
        "daily_image_limit": int(client.get("daily_image_limit", 0)),
        "daily_text_limit": int(client.get("daily_text_limit", 0)),
        "daily_download_limit": int(client.get("daily_download_limit", 0))
    }
    usage = {
        "date_utc": day,
        "requests": req_total,
        "images": img_total,
        "texts": txt_total,
        "downloads": dl_total
    }

    # Update last_seen_at even if suspended/revoked? Spec: suspended/revoked still return identity; do not treat as success request dynamics? We'll update only when status=active.
    if client.get("status") == "active":
        for c in clients:
            if isinstance(c, dict) and c.get("id") == client.get("id"):
                c["last_seen_at"] = now
                c["updated_at"] = now
                break
        _save("api_clients.json", clients)
        _log("get_me", client.get("id"), "ok", None)
    else:
        _log("get_me", client.get("id"), "ok", None)

    return {
        "client": {
            "id": client.get("id"),
            "name": client.get("name"),
            "status": client.get("status"),
            "created_at": client.get("created_at"),
            "updated_at": client.get("updated_at"),
            "last_seen_at": client.get("last_seen_at")
        },
        "scopes": ["generate:image", "generate:text", "download:image"],
        "quota": {"limits": limits, "usage": usage}
    }

def list_generation_requests(api_key, page=None, page_size=None, kind=None, status=None, private=None, model=None, created_after=None, created_before=None, sort=None, order=None, **_extra):
    import json, os, datetime, hashlib, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0002000" if __import__("os").path.isdir("./environment_mix/0002000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_rfc3339(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s.strip():
            return None
        try:
            ss = s.strip()
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(ss)
        except Exception:
            return None

    def _hash_key(k):
        # Stored value is "api_key_hash" with unknown vendor method; support common hashes.
        # Try direct equality to stored hash too (id-style auth).
        if not isinstance(k, str):
            return []
        b = k.encode("utf-8")
        return [
            ("raw", k),
            ("sha256", hashlib.sha256(b).hexdigest()),
            ("sha1", hashlib.sha1(b).hexdigest()),
            ("md5", hashlib.md5(b).hexdigest()),
        ]

    def _auth_client(api_key_value, clients_rows):
        if not isinstance(api_key_value, str) or not api_key_value:
            return None
        # Allow authenticating by client id as well, per rule "match client-visible value or its id".
        for c in clients_rows:
            if c.get("id") == api_key_value:
                return c
        candidates = _hash_key(api_key_value)
        for c in clients_rows:
            h = c.get("api_key_hash")
            if not isinstance(h, str):
                continue
            for _, cand in candidates:
                if cand == h:
                    return c
        return None

    def _log_endpoint(endpoint, client_id, status_code, latency_ms, meta=None):
        # Best-effort request log to generation_requests as audit-only when no dedicated log exists.
        # Use a reserved kind='text' row? Not allowed by constraints for prompt/model.
        # So we only update last_seen_at on success and rely on existing records.
        # However, requirement says "if schema has a usage/audit/request-log collection"; it doesn't.
        # We'll keep minimal observable dynamics by touching api_clients.updated_at/last_seen_at.
        if client_id is None:
            return
        now = _now_iso()
        for c in clients:
            if c.get("id") == client_id:
                c["updated_at"] = now
                if status_code and 200 <= status_code < 300:
                    c["last_seen_at"] = now
                break

    t0 = time.time()

    # Validate inputs
    if not isinstance(api_key, str) or not api_key:
        return _err("VALIDATION_ERROR", "api_key is required and must be a non-empty string", field="api_key")

    if page is None:
        page = 1
    if page_size is None:
        page_size = 50
    if sort is None:
        sort = "created_at"
    if order is None:
        order = "desc"

    if not isinstance(page, int) or page < 1:
        return _err("VALIDATION_ERROR", "page must be an integer >= 1", field="page")
    if not isinstance(page_size, int) or page_size < 1 or page_size > 200:
        return _err("VALIDATION_ERROR", "page_size must be an integer between 1 and 200", field="page_size")
    if kind is not None and kind not in ("image", "text"):
        return _err("VALIDATION_ERROR", "kind must be 'image' or 'text'", field="kind")
    if status is not None and status not in ("queued", "running", "succeeded", "failed", "cancelled"):
        return _err("VALIDATION_ERROR", "status is invalid", field="status")
    if private is not None and not isinstance(private, bool):
        return _err("VALIDATION_ERROR", "private must be boolean", field="private")
    if model is not None and (not isinstance(model, str) or not model):
        return _err("VALIDATION_ERROR", "model must be a non-empty string", field="model")
    if sort not in ("created_at", "updated_at"):
        return _err("VALIDATION_ERROR", "sort must be 'created_at' or 'updated_at'", field="sort")
    if order not in ("asc", "desc"):
        return _err("VALIDATION_ERROR", "order must be 'asc' or 'desc'", field="order")

    ca = _parse_rfc3339(created_after)
    if created_after is not None and ca is None:
        return _err("VALIDATION_ERROR", "created_after must be RFC3339 datetime", field="created_after")
    cb = _parse_rfc3339(created_before)
    if created_before is not None and cb is None:
        return _err("VALIDATION_ERROR", "created_before must be RFC3339 datetime", field="created_before")

    clients = _load("api_clients.json")
    client = _auth_client(api_key, clients)
    if not client:
        return _err("UNAUTHORIZED", "Invalid API key")

    gen = _load("generation_requests.json")

    # Only return rows for this client_id; private only visible to same client (already enforced by filter)
    rows = []
    for r in gen:
        if r.get("client_id") != client.get("id"):
            continue
        if kind is not None and r.get("kind") != kind:
            continue
        if status is not None and r.get("status") != status:
            continue
        if private is not None and bool(r.get("private")) != private:
            continue
        if model is not None and r.get("model") != model:
            continue
        # time filters
        r_created = _parse_rfc3339(r.get("created_at")) if isinstance(r.get("created_at"), str) else None
        if ca is not None and r_created is not None and r_created <= ca:
            continue
        if cb is not None and r_created is not None and r_created >= cb:
            continue
        rows.append(r)

    # sort
    def _key(rr):
        v = rr.get(sort)
        dt = _parse_rfc3339(v) if isinstance(v, str) else None
        return dt if dt is not None else datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)

    rows.sort(key=_key, reverse=(order == "desc"))

    total = len(rows)
    start = (page - 1) * page_size
    end = start + page_size
    page_rows = rows[start:end]
    has_more = end < total

    latency_ms = int((time.time() - t0) * 1000)
    _log_endpoint("list_generation_requests", client.get("id"), 200, latency_ms)
    _save("api_clients.json", clients)

    return {
        "data": page_rows,
        "meta": {
            "page": page,
            "page_size": page_size,
            "total": total,
            "has_more": has_more,
            "next_page": (page + 1) if has_more else None,
            "sort": sort,
            "order": order,
        },
    }

def get_generation_request(api_key, id, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0002000" if __import__("os").path.isdir("./environment_mix/0002000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _rows(obj):
        if isinstance(obj, list):
            return obj
        if isinstance(obj, dict) and isinstance(obj.get("rows"), list):
            return obj["rows"]
        return []

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _append_request_log(endpoint, credential, client_id, status_s, latency_ms, extra=None):
        log_fn = "request_logs.json"
        path = os.path.join(_DB, log_fn)
        if not os.path.exists(path):
            return
        logs = _rows(_load(log_fn))
        row = {
            "id": f"pol_req_{int(time.time()*1000)}_{os.getpid()}",
            "endpoint": endpoint,
            "credential": credential,
            "client_id": client_id,
            "status": status_s,
            "latency_ms": int(latency_ms),
            "timestamp": _now_iso(),
        }
        if isinstance(extra, dict):
            row.update(extra)
        logs.append(row)
        _save(log_fn, logs)

    def _auth_client(api_key_value, clients):
        # Authenticate by client-visible api_key value (stored in api_key_hash column) OR by client id.
        if not isinstance(api_key_value, str) or not api_key_value.strip():
            return None
        v = api_key_value.strip()
        for c in clients:
            if c.get("id") == v:
                return c
        for c in clients:
            if isinstance(c.get("api_key_hash"), str) and c.get("api_key_hash") == v:
                return c
        return None

    t0 = time.time()
    endpoint = "get_generation_request"
    client_id = None
    try:
        if not isinstance(api_key, str) or not api_key.strip():
            _append_request_log(endpoint, api_key, None, "error", (time.time() - t0) * 1000, {"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "api_key must be a non-empty string", field="api_key")
        if not isinstance(id, str) or not id.strip():
            _append_request_log(endpoint, api_key, None, "error", (time.time() - t0) * 1000, {"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "id must be a non-empty string", field="id")

        clients = _rows(_load("api_clients.json"))
        client = _auth_client(api_key, clients)
        if not client:
            _append_request_log(endpoint, api_key, None, "error", (time.time() - t0) * 1000, {"error_code": "UNAUTHORIZED"})
            return _err("UNAUTHORIZED", "invalid api_key")
        client_id = client.get("id")

        gens = _rows(_load("generation_requests.json"))
        gen = None
        for r in gens:
            if r.get("id") == id:
                gen = r
                break
        if not gen:
            _append_request_log(endpoint, api_key, client_id, "error", (time.time() - t0) * 1000, {"error_code": "NOT_FOUND"})
            return _err("NOT_FOUND", "generation_request not found", id=id)

        # Ownership check
        if gen.get("client_id") != client_id:
            _append_request_log(endpoint, api_key, client_id, "error", (time.time() - t0) * 1000, {"error_code": "UNAUTHORIZED"})
            return _err("UNAUTHORIZED", "not allowed to access this generation_request", id=id)

        kind = gen.get("kind")
        product = None
        if gen.get("status") == "succeeded":
            if kind == "image":
                imgs = _rows(_load("image_assets.json"))
                for im in imgs:
                    if im.get("generation_id") == gen.get("id"):
                        # Private assets are allowed for owner; expose only a summary
                        product = {
                            "type": "image_asset",
                            "id": im.get("id"),
                            "status": im.get("status"),
                            "provider_url": im.get("provider_url"),
                            "content_type": im.get("content_type"),
                            "byte_size": im.get("byte_size"),
                            "width": im.get("width"),
                            "height": im.get("height"),
                            "is_private": im.get("is_private"),
                            "sha256": im.get("sha256"),
                        }
                        break
            elif kind == "text":
                outs = _rows(_load("text_outputs.json"))
                for out in outs:
                    if out.get("generation_id") == gen.get("id"):
                        product = {
                            "type": "text_output",
                            "id": out.get("id"),
                            "status": out.get("status"),
                            "format": out.get("format"),
                            "is_private": out.get("is_private"),
                            "token_count_estimate": out.get("token_count_estimate"),
                        }
                        break

        # Update last_seen_at on successful read (best-effort; don't error if missing row)
        now = _now_iso()
        for c in clients:
            if c.get("id") == client_id:
                c["last_seen_at"] = now
                c["updated_at"] = now
                _save("api_clients.json", clients)
                break

        resp = {"generation_request": gen, "product": product}
        _append_request_log(endpoint, api_key, client_id, "ok", (time.time() - t0) * 1000, {"generation_id": id})
        return resp
    except Exception as e:
        _append_request_log(endpoint, api_key, client_id, "error", (time.time() - t0) * 1000, {"error_code": "service_error"})
        return _err("CONFLICT", "internal error", detail=str(e))

def update_generation_request(api_key, id, status=None, error_code=None, error_message=None, provider_request=None, started_at=None, finished_at=None, response_json=None, system_prompt=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0002000" if __import__("os").path.isdir("./environment_mix/0002000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _rows(obj):
        if isinstance(obj, list):
            return obj
        if isinstance(obj, dict) and isinstance(obj.get("rows"), list):
            return obj["rows"]
        return []

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_rfc3339(s):
        if s is None:
            return None, None
        if not isinstance(s, str) or not s.strip():
            return None, "must be an RFC3339 string"
        ss = s.strip()
        if ss.endswith("Z"):
            ss = ss[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(ss)
        except ValueError:
            return None, "must be an RFC3339 string"
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc), None

    def _append_request_log(endpoint, credential, client_id, status_s, latency_ms, extra=None):
        log_fn = "request_logs.json"
        path = os.path.join(_DB, log_fn)
        if not os.path.exists(path):
            return
        logs = _rows(_load(log_fn))
        row = {
            "id": f"pol_req_{int(time.time()*1000)}_{os.getpid()}",
            "endpoint": endpoint,
            "credential": credential,
            "client_id": client_id,
            "status": status_s,
            "latency_ms": int(latency_ms),
            "timestamp": _now_iso(),
        }
        if isinstance(extra, dict):
            row.update(extra)
        logs.append(row)
        _save(log_fn, logs)

    def _auth_client(api_key_value, clients):
        if not isinstance(api_key_value, str) or not api_key_value.strip():
            return None
        v = api_key_value.strip()
        for c in clients:
            if c.get("id") == v:
                return c
        for c in clients:
            if isinstance(c.get("api_key_hash"), str) and c.get("api_key_hash") == v:
                return c
        return None

    def _ulid_like(prefix="pol_"):
        # Time-sortable enough for local store; avoid extra deps.
        t_ms = int(time.time() * 1000)
        return f"{prefix}{t_ms:013d}_{os.getpid()}_{int(time.time_ns()%1000000):06d}"

    t0 = time.time()
    endpoint = "update_generation_request"
    client_id = None
    try:
        # Validate inputs
        if not isinstance(api_key, str) or not api_key.strip():
            _append_request_log(endpoint, api_key, None, "error", (time.time() - t0) * 1000, {"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "api_key must be a non-empty string", field="api_key")
        if not isinstance(id, str) or not id.strip():
            _append_request_log(endpoint, api_key, None, "error", (time.time() - t0) * 1000, {"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "id must be a non-empty string", field="id")

        allowed_status = {"queued", "running", "succeeded", "failed", "cancelled"}
        if status is not None and status not in allowed_status:
            _append_request_log(endpoint, api_key, None, "error", (time.time() - t0) * 1000, {"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "invalid status", field="status", allowed=sorted(allowed_status))

        allowed_error_code = {"quota_exceeded", "invalid_argument", "content_rejected", "service_unavailable", "forbidden", "not_found", "io_error", "validation_error"}
        if error_code is not None and error_code not in allowed_error_code:
            _append_request_log(endpoint, api_key, None, "error", (time.time() - t0) * 1000, {"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "invalid error_code", field="error_code", allowed=sorted(allowed_error_code))

        if error_message is not None and not isinstance(error_message, str):
            _append_request_log(endpoint, api_key, None, "error", (time.time() - t0) * 1000, {"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "error_message must be a string", field="error_message")

        if provider_request is not None and not isinstance(provider_request, str):
            _append_request_log(endpoint, api_key, None, "error", (time.time() - t0) * 1000, {"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "provider_request must be a string", field="provider_request")

        if system_prompt is not None and not isinstance(system_prompt, str):
            _append_request_log(endpoint, api_key, None, "error", (time.time() - t0) * 1000, {"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "system_prompt must be a string or null", field="system_prompt")

        if response_json is not None and not isinstance(response_json, (dict, type(None))):
            _append_request_log(endpoint, api_key, None, "error", (time.time() - t0) * 1000, {"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "response_json must be an object or null", field="response_json")

        dt_started, err = _parse_rfc3339(started_at)
        if err:
            _append_request_log(endpoint, api_key, None, "error", (time.time() - t0) * 1000, {"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", err, field="started_at")
        dt_finished, err = _parse_rfc3339(finished_at)
        if err:
            _append_request_log(endpoint, api_key, None, "error", (time.time() - t0) * 1000, {"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", err, field="finished_at")

        clients = _rows(_load("api_clients.json"))
        client = _auth_client(api_key, clients)
        if not client:
            _append_request_log(endpoint, api_key, None, "error", (time.time() - t0) * 1000, {"error_code": "UNAUTHORIZED"})
            return _err("UNAUTHORIZED", "invalid api_key")
        client_id = client.get("id")

        gens = _rows(_load("generation_requests.json"))
        gen_idx = None
        for i, r in enumerate(gens):
            if r.get("id") == id:
                gen_idx = i
                break
        if gen_idx is None:
            _append_request_log(endpoint, api_key, client_id, "error", (time.time() - t0) * 1000, {"error_code": "NOT_FOUND"})
            return _err("NOT_FOUND", "generation_request not found", id=id)

        gen = gens[gen_idx]

        # Ownership check
        if gen.get("client_id") != client_id:
            _append_request_log(endpoint, api_key, client_id, "error", (time.time() - t0) * 1000, {"error_code": "UNAUTHORIZED"})
            return _err("UNAUTHORIZED", "not allowed to modify this generation_request", id=id)

        # Terminal state conflict
        if gen.get("status") in ("succeeded", "failed", "cancelled"):
            # No changes allowed once terminal per tool description
            _append_request_log(endpoint, api_key, client_id, "error", (time.time() - t0) * 1000, {"error_code": "CONFLICT"})
            return _err("CONFLICT", "generation_request is in a terminal state and cannot be modified", id=id, status=gen.get("status"))

        # Validate kind-specific fields (what can be written)
        kind = gen.get("kind")
        if kind == "image":
            if response_json is not None:
                _append_request_log(endpoint, api_key, client_id, "error", (time.time() - t0) * 1000, {"error_code": "VALIDATION_ERROR"})
                return _err("VALIDATION_ERROR", "response_json must be null for kind='image'", field="response_json")
            if system_prompt is not None:
                _append_request_log(endpoint, api_key, client_id, "error", (time.time() - t0) * 1000, {"error_code": "VALIDATION_ERROR"})
                return _err("VALIDATION_ERROR", "system_prompt must be null for kind='image'", field="system_prompt")
        elif kind == "text":
            # response_json allowed only when generation_requests.response_json truthy
            if response_json is not None:
                if not gen.get("response_json"):
                    _append_request_log(endpoint, api_key, client_id, "error", (time.time() - t0) * 1000, {"error_code": "VALIDATION_ERROR"})
                    return _err("VALIDATION_ERROR", "response_json can only be set when the request was created with json=true", field="response_json")
        else:
            _append_request_log(endpoint, api_key, client_id, "error", (time.time() - t0) * 1000, {"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "invalid generation_request.kind", kind=kind)

        # State machine transitions
        transitions = {
            "queued": {"running", "cancelled", "failed"},
            "running": {"succeeded", "failed", "cancelled"},
            "succeeded": set(),
            "failed": set(),
            "cancelled": set(),
        }
        if status is not None:
            cur = gen.get("status")
            if status != cur:
                if status not in transitions.get(cur, set()):
                    _append_request_log(endpoint, api_key, client_id, "error", (time.time() - t0) * 1000, {"error_code": "INVALID_TRANSITION"})
                    return _err("INVALID_TRANSITION", "status transition not allowed", from_status=cur, to_status=status)

        # If failing, require error_code; if error_code provided ensure status is failed or being set to failed
        target_status = status if status is not None else gen.get("status")
        if target_status == "failed" and error_code is None and gen.get("error_code") in (None, ""):
            _append_request_log(endpoint, api_key, client_id, "error", (time.time() - t0) * 1000, {"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "error_code is required when status=failed", field="error_code")
        if error_code is not None and target_status != "failed":
            _append_request_log(endpoint, api_key, client_id, "error", (time.time() - t0) * 1000, {"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "error_code can only be set when status=failed", field="error_code")

        now = _now_iso()

        # Apply updates
        changed = False
        if status is not None and status != gen.get("status"):
            gen["status"] = status
            changed = True
            if status == "running":
                if gen.get("started_at") is None:
                    gen["started_at"] = now
            if status in ("succeeded", "failed", "cancelled"):
                if gen.get("finished_at") is None:
                    gen["finished_at"] = now

        # Set extra fields
        if error_code is not None and error_code != gen.get("error_code"):
            gen["error_code"] = error_code
            changed = True
        if error_message is not None and error_message != gen.get("error_message"):
            gen["error_message"] = error_message
            changed = True
        if provider_request is not None:
            # schema expects object, but tool passes string "摘要/标识" and audit requires relaxing:
            # store it inside provider_request as {"summary": "..."} to keep type correctness.
            cur = gen.get("provider_request")
            desired = {"summary": provider_request}
            if cur != desired:
                gen["provider_request"] = desired
                changed = True
        if dt_started is not None:
            iso = dt_started.replace(microsecond=0).isoformat().replace("+00:00", "Z")
            if gen.get("started_at") != iso:
                gen["started_at"] = iso
                changed = True
        if dt_finished is not None:
            iso = dt_finished.replace(microsecond=0).isoformat().replace("+00:00", "Z")
            if gen.get("finished_at") != iso:
                gen["finished_at"] = iso
                changed = True
        if response_json is not None:
            if gen.get("response_json") != response_json:
                gen["response_json"] = response_json
                changed = True
        if system_prompt is not None:
            if gen.get("system_prompt") != system_prompt:
                gen["system_prompt"] = system_prompt
                changed = True

        if not changed:
            # No success without effect: if user requested no-op, treat as conflict to signal no change.
            _append_request_log(endpoint, api_key, client_id, "error", (time.time() - t0) * 1000, {"error_code": "CONFLICT"})
            return _err("CONFLICT", "no changes applied", id=id)

        gen["updated_at"] = now
        gens[gen_idx] = gen
        _save("generation_requests.json", gens)

        # If succeeded, enforce existence of exactly one product record (create if missing; reject if ambiguous)
        if gen.get("status") == "succeeded":
            if kind == "image":
                imgs = _rows(_load("image_assets.json"))
                matches = [im for im in imgs if im.get("generation_id") == gen.get("id")]
                if len(matches) == 0:
                    # Create a minimal asset row consistent with request dimensions.
                    w = gen.get("image_width")
                    h = gen.get("image_height")
                    if not isinstance(w, int) or not isinstance(h, int):
                        _append_request_log(endpoint, api_key, client_id, "error", (time.time() - t0) * 1000, {"error_code": "CONFLICT"})
                        return _err("CONFLICT", "cannot finalize succeeded image generation without width/height", id=id)
                    asset = {
                        "id": _ulid_like("pol_img_"),
                        "generation_id": gen.get("id"),
                        "status": "available",
                        "provider_url": "http://localhost/placeholder",  # best-effort placeholder; real upstream URL may be written later
                        "content_type": None,
                        "byte_size": None,
                        "sha256": None,
                        "width": w,
                        "height": h,
                        "is_private": bool(gen.get("private")),
                        "created_at": now,
                        "updated_at": now,
                    }
                    imgs.append(asset)
                    _save("image_assets.json", imgs)
                elif len(matches) > 1:
                    _append_request_log(endpoint, api_key, client_id, "error", (time.time() - t0) * 1000, {"error_code": "CONFLICT"})
                    return _err("CONFLICT", "data integrity error: multiple image_assets for generation_id", generation_id=gen.get("id"))
            else:
                outs = _rows(_load("text_outputs.json"))
                matches = [o for o in outs if o.get("generation_id") == gen.get("id")]
                if len(matches) == 0:
                    fmt = "json" if gen.get("response_json") else "plain"
                    out = {
                        "id": _ulid_like("pol_txt_"),
                        "generation_id": gen.get("id"),
                        "status": "available",
                        "format": fmt,
                        "content_text": None,
                        "content_json": None,
                        "is_private": bool(gen.get("private")),
                        "token_count_estimate": None,
                        "created_at": now,
                        "updated_at": now,
                    }
                    # Populate content if provided
                    if fmt == "json":
                        out["content_json"] = gen.get("response_json") if isinstance(gen.get("response_json"), dict) else {}
                    else:
                        out["content_text"] = gen.get("error_message") or ""  # fallback non-null; real service would store model output
                    outs.append(out)
                    _save("text_outputs.json", outs)
                elif len(matches) > 1:
                    _append_request_log(endpoint, api_key, client_id, "error", (time.time() - t0) * 1000, {"error_code": "CONFLICT"})
                    return _err("CONFLICT", "data integrity error: multiple text_outputs for generation_id", generation_id=gen.get("id"))

        # Update last_seen_at on successful mutation
        for c in clients:
            if c.get("id") == client_id:
                c["last_seen_at"] = now
                c["updated_at"] = now
                _save("api_clients.json", clients)
                break

        _append_request_log(endpoint, api_key, client_id, "ok", (time.time() - t0) * 1000, {"generation_id": id})
        return {"generation_request": gen}
    except Exception as e:
        _append_request_log(endpoint, api_key, client_id, "error", (time.time() - t0) * 1000, {"error_code": "service_error"})
        return _err("CONFLICT", "internal error", detail=str(e))

def list_image_assets(api_key, page=None, page_size=None, generation_id=None, status=None, include_deleted=None, created_after=None, created_before=None, sort=None, order=None, **_extra):
    import json, os, datetime, hashlib, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0002000" if __import__("os").path.isdir("./environment_mix/0002000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_rfc3339(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s.strip():
            return None
        try:
            ss = s.strip()
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(ss)
        except Exception:
            return None

    def _hash_key(k):
        if not isinstance(k, str):
            return []
        b = k.encode("utf-8")
        return [
            ("raw", k),
            ("sha256", hashlib.sha256(b).hexdigest()),
            ("sha1", hashlib.sha1(b).hexdigest()),
            ("md5", hashlib.md5(b).hexdigest()),
        ]

    def _auth_client(api_key_value, clients_rows):
        if not isinstance(api_key_value, str) or not api_key_value:
            return None
        for c in clients_rows:
            if c.get("id") == api_key_value:
                return c
        candidates = _hash_key(api_key_value)
        for c in clients_rows:
            h = c.get("api_key_hash")
            if not isinstance(h, str):
                continue
            for _, cand in candidates:
                if cand == h:
                    return c
        return None

    def _touch_client(clients_rows, client_id, ok):
        now = _now_iso()
        for c in clients_rows:
            if c.get("id") == client_id:
                c["updated_at"] = now
                if ok:
                    c["last_seen_at"] = now
                break

    t0 = time.time()

    if not isinstance(api_key, str) or not api_key:
        return _err("VALIDATION_ERROR", "api_key is required and must be a non-empty string", field="api_key")

    if page is None:
        page = 1
    if page_size is None:
        page_size = 50
    if sort is None:
        sort = "created_at"
    if order is None:
        order = "desc"
    if include_deleted is None:
        include_deleted = False
    if status is None:
        status = "available"

    if not isinstance(page, int) or page < 1:
        return _err("VALIDATION_ERROR", "page must be an integer >= 1", field="page")
    if not isinstance(page_size, int) or page_size < 1 or page_size > 200:
        return _err("VALIDATION_ERROR", "page_size must be an integer between 1 and 200", field="page_size")
    if generation_id is not None and (not isinstance(generation_id, str) or not generation_id):
        return _err("VALIDATION_ERROR", "generation_id must be a non-empty string", field="generation_id")
    if status is not None and status not in ("available", "deleted"):
        return _err("VALIDATION_ERROR", "status must be 'available' or 'deleted'", field="status")
    if include_deleted is not None and not isinstance(include_deleted, bool):
        return _err("VALIDATION_ERROR", "include_deleted must be boolean", field="include_deleted")
    if sort not in ("created_at", "updated_at"):
        return _err("VALIDATION_ERROR", "sort must be 'created_at' or 'updated_at'", field="sort")
    if order not in ("asc", "desc"):
        return _err("VALIDATION_ERROR", "order must be 'asc' or 'desc'", field="order")

    ca = _parse_rfc3339(created_after)
    if created_after is not None and ca is None:
        return _err("VALIDATION_ERROR", "created_after must be RFC3339 datetime", field="created_after")
    cb = _parse_rfc3339(created_before)
    if created_before is not None and cb is None:
        return _err("VALIDATION_ERROR", "created_before must be RFC3339 datetime", field="created_before")

    clients = _load("api_clients.json")
    client = _auth_client(api_key, clients)
    if not client:
        return _err("UNAUTHORIZED", "Invalid API key")

    gens = _load("generation_requests.json")
    gen_by_id = {g.get("id"): g for g in gens if isinstance(g, dict) and g.get("id")}

    assets = _load("image_assets.json")

    rows = []
    for a in assets:
        gid = a.get("generation_id")
        g = gen_by_id.get(gid)
        if not g:
            continue
        # Only assets whose generation belongs to this client
        if g.get("client_id") != client.get("id"):
            continue
        # Private visible only to same client (already enforced)
        if bool(a.get("is_private")) and g.get("client_id") != client.get("id"):
            continue
        if generation_id is not None and gid != generation_id:
            continue

        a_status = a.get("status")
        if include_deleted:
            if status is not None and a_status != status:
                continue
        else:
            # default: only non-deleted
            if a_status == "deleted":
                continue
            if status is not None and status != "available":
                # if caller asks deleted but include_deleted is false, return none
                continue

        a_created = _parse_rfc3339(a.get("created_at")) if isinstance(a.get("created_at"), str) else None
        if ca is not None and a_created is not None and a_created <= ca:
            continue
        if cb is not None and a_created is not None and a_created >= cb:
            continue

        rows.append(a)

    def _key(rr):
        v = rr.get(sort)
        dt = _parse_rfc3339(v) if isinstance(v, str) else None
        return dt if dt is not None else datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)

    rows.sort(key=_key, reverse=(order == "desc"))

    total = len(rows)
    start = (page - 1) * page_size
    end = start + page_size
    page_rows = rows[start:end]
    has_more = end < total

    latency_ms = int((time.time() - t0) * 1000)
    _touch_client(clients, client.get("id"), True)
    _save("api_clients.json", clients)

    return {
        "data": page_rows,
        "meta": {
            "page": page,
            "page_size": page_size,
            "total": total,
            "has_more": has_more,
            "next_page": (page + 1) if has_more else None,
            "sort": sort,
            "order": order,
            "include_deleted": include_deleted,
        },
    }

def update_image_asset(api_key, id, status, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0002000" if __import__("os").path.isdir("./environment_mix/0002000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _rows(obj):
        if isinstance(obj, list):
            return obj
        if isinstance(obj, dict) and isinstance(obj.get("rows"), list):
            return obj["rows"]
        return []

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _append_request_log(endpoint, credential, client_id, status_s, latency_ms, extra=None):
        log_fn = "request_logs.json"
        path = os.path.join(_DB, log_fn)
        if not os.path.exists(path):
            return
        logs = _rows(_load(log_fn))
        row = {
            "id": f"pol_req_{int(time.time()*1000)}_{os.getpid()}",
            "endpoint": endpoint,
            "credential": credential,
            "client_id": client_id,
            "status": status_s,
            "latency_ms": int(latency_ms),
            "timestamp": _now_iso(),
        }
        if isinstance(extra, dict):
            row.update(extra)
        logs.append(row)
        _save(log_fn, logs)

    def _auth_client(api_key_value, clients):
        if not isinstance(api_key_value, str) or not api_key_value.strip():
            return None
        v = api_key_value.strip()
        for c in clients:
            if c.get("id") == v:
                return c
        for c in clients:
            if isinstance(c.get("api_key_hash"), str) and c.get("api_key_hash") == v:
                return c
        return None

    t0 = time.time()
    endpoint = "update_image_asset"
    client_id = None
    try:
        if not isinstance(api_key, str) or not api_key.strip():
            _append_request_log(endpoint, api_key, None, "error", (time.time() - t0) * 1000, {"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "api_key must be a non-empty string", field="api_key")
        if not isinstance(id, str) or not id.strip():
            _append_request_log(endpoint, api_key, None, "error", (time.time() - t0) * 1000, {"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "id must be a non-empty string", field="id")
        if status not in ("available", "deleted"):
            _append_request_log(endpoint, api_key, None, "error", (time.time() - t0) * 1000, {"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "invalid status", field="status", allowed=["available", "deleted"])

        clients = _rows(_load("api_clients.json"))
        client = _auth_client(api_key, clients)
        if not client:
            _append_request_log(endpoint, api_key, None, "error", (time.time() - t0) * 1000, {"error_code": "UNAUTHORIZED"})
            return _err("UNAUTHORIZED", "invalid api_key")
        client_id = client.get("id")

        imgs = _rows(_load("image_assets.json"))
        idx = None
        for i, im in enumerate(imgs):
            if im.get("id") == id:
                idx = i
                break
        if idx is None:
            _append_request_log(endpoint, api_key, client_id, "error", (time.time() - t0) * 1000, {"error_code": "NOT_FOUND"})
            return _err("NOT_FOUND", "image_asset not found", id=id)

        im = imgs[idx]

        # Ownership: resolve via generation_requests.client_id
        gens = _rows(_load("generation_requests.json"))
        gen = None
        for g in gens:
            if g.get("id") == im.get("generation_id"):
                gen = g
                break
        if not gen:
            _append_request_log(endpoint, api_key, client_id, "error", (time.time() - t0) * 1000, {"error_code": "CONFLICT"})
            return _err("CONFLICT", "data integrity error: generation_request missing for image_asset", id=id, generation_id=im.get("generation_id"))

        if gen.get("client_id") != client_id:
            _append_request_log(endpoint, api_key, client_id, "error", (time.time() - t0) * 1000, {"error_code": "UNAUTHORIZED"})
            return _err("UNAUTHORIZED", "not allowed to modify this image_asset", id=id)

        # State machine: available -> deleted only; deleted terminal
        cur = im.get("status")
        if cur == "deleted":
            _append_request_log(endpoint, api_key, client_id, "error", (time.time() - t0) * 1000, {"error_code": "CONFLICT"})
            return _err("CONFLICT", "image_asset is deleted and cannot be modified", id=id)
        if cur == "available":
            if status == "available":
                _append_request_log(endpoint, api_key, client_id, "error", (time.time() - t0) * 1000, {"error_code": "CONFLICT"})
                return _err("CONFLICT", "no changes applied", id=id)
            if status != "deleted":
                _append_request_log(endpoint, api_key, client_id, "error", (time.time() - t0) * 1000, {"error_code": "INVALID_TRANSITION"})
                return _err("INVALID_TRANSITION", "status transition not allowed", from_status=cur, to_status=status)

        now = _now_iso()
        im["status"] = "deleted"
        im["updated_at"] = now
        imgs[idx] = im
        _save("image_assets.json", imgs)

        # Update last_seen_at
        for c in clients:
            if c.get("id") == client_id:
                c["last_seen_at"] = now
                c["updated_at"] = now
                _save("api_clients.json", clients)
                break

        _append_request_log(endpoint, api_key, client_id, "ok", (time.time() - t0) * 1000, {"image_id": id})
        return {"image_asset": im}
    except Exception as e:
        _append_request_log(endpoint, api_key, client_id, "error", (time.time() - t0) * 1000, {"error_code": "service_error"})
        return _err("CONFLICT", "internal error", detail=str(e))
